    questionText: "Distinguish between an Embargo and a Quota.",
    tariffModel: {"kind":"fixed","notation":"2@5m(3+2)"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Embargo: This is a total ban on the import of goods from one particular country. It is often done for political reasons.", marks: 5, contextNote: "The scheme illustrates an embargo with \"The American government placed a blanket embargo on the import of UK beef because of the high levels of BSE in the UK.\"", openList: true },
    { id: "r-2", kind: "point", verbatim: "Quota: Quotas are limits imposed on the import of goods and services. Quotas are used as a trade barrier to limit the amount of a certain type of product and or the amount of goods from a certain country that can be imported.", marks: 5, contextNote: "The scheme illustrates a quota with \"The EU imposing a quota on the beef and lamb produce that can be imported from outside the EU.\"", openList: true },
    ],
