    schemeCitation: "Marking points quoted from the SEC marking scheme, Business 2021 Higher Level — © State Examinations Commission.",
    id: "bus-2021-hl-s3-q2cii", topicId: "business-5-16", conceptId: "benefits-of-community-development",
    section: "3", questionRef: "2021 HL Section 3 Q2(C)(ii)",
