    id: "bus-2024-hl-s3-q8bii", topicId: "business-4-17", conceptId: "generic-versus-persuasive-advertising",
    section: "3", questionRef: "2024 HL Section 3 Q8(B)(ii)",
    stem: "The ASAI published fresh guidance for Irish influencers on the clear labelling of ads on social media. For the avoidance of confusion, all commercial content should now be labelled #Ad (or #Fógra for Irish‐language posts). October 2023",
    questionText: "Distinguish between generic advertising and persuasive advertising.",
    tariffModel: {"kind":"fixed","notation":"2@5m(2+3)"}, totalMarks: 10,
    rows: [
    { id: "r-1", kind: "point", verbatim: "Generic advertising is used to prompt the consumer to think about a type of product rather than a specific brand. E.g. The National Dairy Council encouraging the consumption of milk.", marks: 5, openList: true },
    { id: "r-2", kind: "point", verbatim: "Persuasive advertising: This advertising attempts to entice the consumer that they need the product. Persuasive advertising attempts to convey the message that this product/service will bring value to the consumers life. E.g. L’Oréal try to persuade the consumer they will have healthier/more attractive hair as a result of using their products.", marks: 5, openList: true },
    ],
